<template><view class="wrap ui-page"><view class="banner"><text class="eyebrow">EVERYDAY SELECTS</text><text class="title">发现今天的好物</text><text class="desc">精选商品，快速到店核销</text></view><view class="search"><text class="search-icon">⌕</text><input v-model.trim="keyword" placeholder="搜索商品" confirm-type="search" @confirm="goGoods"/><text class="search-action" @tap="goGoods">搜索</text></view><view class="section-title"><text>热门分类</text><text class="more" @tap="goGoods">查看全部</text></view><view class="categories"><view v-for="c in categories" :key="c.id||c.code" class="category" @tap="goGoods(c.id)">{{c.name}}</view><view v-if="categoryError" class="category-error">{{categoryError}}</view></view><view class="grid"><view class="item" @tap="goGoods()"><text class="tile-icon">◈</text><text>逛商城</text></view><view class="item" @tap="goPoints"><text class="tile-icon">✦</text><text>积分中心</text></view><view class="item" @tap="goOrders"><text class="tile-icon">▤</text><text>我的订单</text></view></view></view></template>
<script setup lang="ts">import {ref} from 'vue';import {apiRequest} from '@mall/uni-shared';const keyword=ref(''),categories=ref<any[]>([]),categoryError=ref('');apiRequest<any>({url:'/api/c/category'}).then((d)=>{categories.value=Array.isArray(d)?d:d?.list??[]}).catch((e:any)=>{categoryError.value=e.message||'分类服务暂不可用'});function goGoods(categoryId?:number){uni.setStorageSync('c_goods_filters',{keyword:keyword.value,categoryId});uni.switchTab({url:'/pages/goods/index'})}function goPoints(){uni.navigateTo({url:'/pages/points/index'})}function goOrders(){uni.switchTab({url:'/pages/order/list'})}</script>
<style scoped>.banner{padding:48rpx 38rpx;background:linear-gradient(135deg,#173d4f,#168f86);color:#fff;border-radius:32rpx;box-shadow:0 16rpx 32rpx #168f8630}.eyebrow{display:block;opacity:.72;font-size:20rpx;letter-spacing:3rpx}.title{display:block;font-size:44rpx;font-weight:750;margin:14rpx 0}.desc{opacity:.8;font-size:26rpx}.search{display:flex;align-items:center;background:#fff;border-radius:22rpx;padding:20rpx 24rpx;margin-top:26rpx;box-shadow:0 8rpx 20rpx #1720330a}.search input{flex:1;margin:0 14rpx}.search-icon,.search-action{color:#168f86}.search-action{font-weight:600;font-size:26rpx}.section-title{display:flex;justify-content:space-between;align-items:center;font-size:32rpx;font-weight:700;margin-top:42rpx}.more{color:#8d99aa;font-size:24rpx;font-weight:400}.categories{display:flex;gap:16rpx;overflow:auto;margin-top:20rpx;padding-bottom:4rpx}.category{background:#fff;border-radius:16rpx;padding:17rpx 24rpx;white-space:nowrap;color:#46546b;box-shadow:0 5rpx 14rpx #17203308}.category-error{color:#999;font-size:24rpx}.grid{display:flex;gap:18rpx;margin-top:28rpx}.item{flex:1;background:#fff;padding:28rpx 8rpx;text-align:center;border-radius:22rpx;display:flex;flex-direction:column;gap:12rpx;color:#405069;font-size:24rpx;box-shadow:0 8rpx 18rpx #17203308}.tile-icon{font-size:38rpx;color:#168f86}</style>
